(() => {
  const sections = [...document.querySelectorAll('div[aria-label], section, [class*="section"]')].map(el => el.getAttribute('aria-label') || el.className).filter(Boolean);
  return sections.slice(0, 50);
})()

(() => {
  const inputs = [...document.querySelectorAll('input')].map(el => ({
    name: el.name, id: el.id, placeholder: el.placeholder,
    ariaLabel: el.getAttribute('aria-label'),
    value: el.value,
    type: el.type
  }));
  return inputs;
})()

(() => {
  const els = [...document.querySelectorAll('div, section, button, summary')].filter(el => el.textContent && el.textContent.trim() === 'Panel options');
  return els.map(el => ({tag: el.tagName, cls: el.className, expanded: el.getAttribute('aria-expanded'), html: el.outerHTML.slice(0, 300)}));
})()

(() => {
  const els = [...document.querySelectorAll('div, section, button, summary, span, h3')].filter(el => el.textContent && el.textContent.toLowerCase().includes('panel options'));
  return els.map(el => ({tag: el.tagName, cls: String(el.className).slice(0,80), text: el.textContent.trim().slice(0,60)}));
})()

(() => {
  // Look for the right-side panel editor tabs/sections
  const els = [...document.querySelectorAll('button, [role="tab"], [class*="tab"]')].map(el => ({tag: el.tagName, text: (el.textContent||'').trim().slice(0,40), cls: String(el.className).slice(0,60)})).filter(e => e.text);
  return els.slice(0, 60);
})()

(() => {
  // Find collapsible section headers in the right sidebar
  const sidebar = document.querySelector('[class*="panelOptionsSidebar"], [class*="panel-options"], [class*="sidebar"]');
  const all = [...document.querySelectorAll('div')].filter(d => {
    const c = String(d.className);
    return c.includes('collapse') || c.includes('section');
  }).slice(0, 30).map(d => ({cls: String(d.className).slice(0,80), text: (d.textContent||'').trim().slice(0,50)}));
  return {sidebarFound: !!sidebar, all};
})()

(() => {
  // The right pane with visualization options — find headings/collapse headers
  const heads = [...document.querySelectorAll('h3, h4, [class*="Heading"], [class*="heading"], [class*="Collapse"]')].map(el => ({tag: el.tagName, cls: String(el.className).slice(0,70), text: (el.textContent||'').trim().slice(0,60)})).filter(h => h.text);
  return heads.slice(0, 40);
})()

(() => {
  // Find elements containing the word "Panel" as text
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const hits = [];
  let node;
  while ((node = walker.nextNode())) {
    const t = node.textContent;
    if (t && t.trim() && t.trim().length < 40 && /panel/i.test(t)) {
      hits.push({text: t.trim(), parentTag: node.parentElement.tagName, parentCls: String(node.parentElement.className).slice(0,60)});
    }
  }
  return hits.slice(0, 30);
})()

(() => {
  const modal = document.querySelector('[role="dialog"], [class*="modal"]');
  const saveBtns = [...document.querySelectorAll('button')].filter(b => /save/i.test(b.textContent||'')).map(b => b.textContent.trim());
  return {modal: modal ? modal.textContent.slice(0, 200) : null, saveBtns};
})()

(() => {
  const modal = document.querySelector('[role="dialog"], [class*="modal"]');
  const inputs = [...modal.querySelectorAll('input')].map(i => ({id: i.id, name: i.name, ariaLabel: i.getAttribute('aria-label'), placeholder: i.placeholder, value: i.value, type: i.type}));
  return inputs;
})()

(() => {
  const modal = document.querySelector('[role="dialog"], [class*="modal"]');
  return {modalText: modal ? modal.textContent.slice(0, 300) : null, url: location.href};
})()
